describe('Modal Focus Trapping', () => {
  beforeEach(() => {
    cy.visit('/modal');
  });

  it('should trap focus inside open modal when clicking outside', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal is visible
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-body"]').should('be.visible');

    // Click outside modal to test focus trapping
    cy.get('[data-testid="background-content"]').click();

    // Verify focus is still inside modal
    cy.get('[data-testid="modal-close-btn"]').should('have.focus');
    cy.get('[data-testid="modal-body"]').should('have.focus');

    // Close modal
    cy.get('[data-testid="modal-close-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should not trap focus when modal is closed', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Click outside modal to test focus behavior
    cy.get('[data-testid="background-content"]').click();

    // Verify focus is not trapped outside modal
    cy.get('[data-testid="modal-close-btn"]').should('not.have.focus');
    cy.get('[data-testid="modal-body"]').should('not.have.focus');

    // Close modal
    cy.get('[data-testid="modal-close-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });
});
